const fs = require('fs');
const ExcelJS = require('exceljs');

async function processAll() {
  const filePath = 'C:\\\\Users\\\\lg\\\\Desktop\\\\오늘\\\\(데이터검증팀)실사 DB 취합_전달용_260720_배현명.xlsx';
  const backupPath = 'C:\\\\Users\\\\lg\\\\Desktop\\\\오늘\\\\(데이터검증팀)실사 DB 취합_전달용_260720_배현명_backup_11847_12000.xlsx';

  console.log('Restoring from backup...');
  fs.copyFileSync(backupPath, filePath);

  console.log('Reading verified TSV...');
  const tsvLines = fs.readFileSync('rows_11847_12000_verified.tsv', 'utf-8').split('\n').filter(l => l.trim().length > 0);

  console.log('Loading workbook...');
  const workbook = new ExcelJS.Workbook();
  await workbook.xlsx.readFile(filePath);
  const sheet = workbook.getWorksheet('기업 정보');

  const orangeFill = {
    type: 'pattern',
    pattern: 'solid',
    fgColor: { argb: 'FFFFA500' } // Standard clear Orange
  };

  let modifiedCellCount = 0;

  for (let i = 0; i < tsvLines.length; i++) {
    const rowNum = 11847 + i;
    const row = sheet.getRow(rowNum);
    const p = tsvLines[i].split('\t');

    // Mapping:
    // Col 1: 작성자 ('배현명')
    // Col 2: 비고 (상태)
    // Col 3: 회사명
    // Col 4: 사업자번호
    // Col 5: 대표자
    // Col 6: 우편번호
    // Col 7: 주소
    // Col 8: 전화번호
    // Col 9: 팩스번호
    // Col 10: 홈페이지
    // Col 11: 이메일
    // Col 15: 종업원수
    // Col 18: 업종 (NICE)
    // Col 25: 법인번호
    // Col 31: 결산월
    // Col 48: 업종_대
    // Col 49: 업종_중
    // Col 50: 업종_소

    const newValues = {
      1: p[0] || '배현명',
      2: p[1] || null,
      3: p[2] || null,
      4: p[3] ? (isNaN(p[3]) ? p[3] : Number(p[3])) : null,
      5: p[4] || null,
      6: p[5] ? (isNaN(p[5]) ? p[5] : Number(p[5])) : null,
      7: p[6] || null,
      8: p[7] || null,
      9: p[8] || null,
      10: p[9] || null,
      11: p[10] || null,
      15: p[11] ? (isNaN(p[11]) ? p[11] : Number(p[11])) : null,
      18: p[12] || null,
      25: p[13] || null,
      31: p[14] || null,
      48: p[15] || null,
      49: p[16] || null,
      50: p[17] || null
    };

    for (const [colStr, newVal] of Object.entries(newValues)) {
      const col = Number(colStr);
      const origVal = row.getCell(col).value;

      const normOrig = origVal === null || origVal === undefined ? '' : String(origVal).trim();
      const normNew = newVal === null || newVal === undefined ? '' : String(newVal).trim();

      // Update value
      row.getCell(col).value = newVal;

      // If newly added or modified from original, apply orange fill
      if (normNew !== '' && normNew !== normOrig) {
        row.getCell(col).fill = orangeFill;
        modifiedCellCount++;
      }
    }

    row.commit();
  }

  console.log('Total modified/added cells highlighted in orange:', modifiedCellCount);
  console.log('Writing file to temp...');
  const tempPath = filePath + '.tmp';
  await workbook.xlsx.writeFile(tempPath);

  console.log('Replacing target file with temp file...');
  if (fs.existsSync(filePath)) {
    fs.unlinkSync(filePath);
  }
  fs.renameSync(tempPath, filePath);

  console.log('Done! Final file size:', fs.statSync(filePath).size);
}

processAll().catch(console.error);
